using FrontEnd.Scanning;
using FrontEnd.Tokens;
using Intermediate.Code.Interfaces;
using Intermediate.Symbols.Interfaces;
using Messaging;

namespace FrontEnd.Parsing;

/// <summary>
/// Provides a language-independent base for parsers.
/// Language-specific parsers derive from this class.
/// </summary>
public abstract class Parser : IMessageProducer
{
    /// <summary>
    /// Gets the scanner that supplies this parser's tokens.
    /// </summary>
    protected Scanner Scanner { get; }

    /// <summary>
    /// Gets the intermediate code generated by this parser.
    /// </summary>
    public IIntermediateCode Code => TranslationContext.Code;

    /// <summary>
    /// Gets the root symbol table for this translation.
    /// </summary>
    public ISymbolTable SymbolTable => TranslationContext.SymbolTable;

    /// <summary>
    /// Gets the symbol table stack for this translation.
    /// </summary>
    public ISymbolTableStack SymbolTableStack => TranslationContext.SymbolTableStack;

    /// <summary>
    /// Gets the translation state shared by this parser and its child parsers.
    /// </summary>
    protected TranslationContext TranslationContext { get; }

    /// <summary>
    /// Initializes the root parser state for one translation.
    /// </summary>
    /// <param name="scanner">The scanner that supplies the source tokens.</param>
    protected Parser(Scanner scanner, TranslationContext translationContext)
    {
        ArgumentNullException.ThrowIfNull(scanner);
        ArgumentNullException.ThrowIfNull(translationContext);

        Scanner = scanner;
        TranslationContext = translationContext;
    }

    /// <summary>
    /// Initializes a child parser that shares the translation state of its parent.
    /// </summary>
    /// <param name="parent">The parent parser whose translation state is reused.</param>
    protected Parser(Parser parent)
    {
        ArgumentNullException.ThrowIfNull(parent);

        Scanner = parent.Scanner;
        TranslationContext = parent.TranslationContext;
    }

    /// <summary>
    /// Parses a source program and generates the intermediate code and the symbol table.
    /// To be implemented by a language-specific parser subclass.
    /// </summary>
    /// <exception cref="Exception">
    /// Thrown if an error occurs during parsing.
    /// </exception>
    public abstract void Parse();

    /// <summary>
    /// Gets the number of syntax errors found by the parser.
    /// To be implemented by a language-specific parser subclass.
    /// </summary>
    public abstract int ErrorCount { get; }

    /// <summary>
    /// Calls the scanner's <see cref="Scanner.CurrentToken"/> method.
    /// </summary>
    /// <returns>The current token.</returns>
    /// <exception cref="InvalidOperationException">Thrown before the scanner has extracted a token.</exception>
    public Token CurrentToken()
    {
        return Scanner.CurrentToken()
            ?? throw new InvalidOperationException("The scanner has not extracted a token.");
    }

    /// <summary>
    /// Calls the scanner's <see cref="Scanner.NextToken"/> method.
    /// </summary>
    /// <returns>The next token.</returns>
    /// <exception cref="Exception">
    /// Thrown if an error occurs while retrieving the next token.
    /// </exception>
    protected Token NextToken()
    {
        return Scanner.NextToken();
    }

    /// <summary>
    /// Add a parser message listener.
    /// </summary>
    /// <param name="listener">The listener to add.</param>
    public void AddMessageListener(IMessageListener listener)
    {
        TranslationContext.MessageHandler.AddListener(listener);
    }

    /// <summary>
    /// Remove a parser message listener.
    /// </summary>
    /// <param name="listener">The listener to remove.</param>
    public void RemoveMessageListener(IMessageListener listener)
    {
        TranslationContext.MessageHandler.RemoveListener(listener);
    }

    /// <summary>
    /// Notify listeners after setting the message.
    /// </summary>
    /// <param name="message">The message to publish.</param>
    public void SendMessage(Message message)
    {
        TranslationContext.MessageHandler.SendMessage(message);
    }
}
